        OR s.applicant_name ILIKE '%' || btrim(p_search) || '%'
        OR s.employee_no ILIKE '%' || btrim(p_search) || '%'
        OR s.emploc_no ILIKE '%' || btrim(p_search) || '%'
        OR s.vcode ILIKE '%' || btrim(p_search) || '%'
        OR s.account_name ILIKE '%' || btrim(p_search) || '%'
        OR s.store_name ILIKE '%' || btrim(p_search) || '%'
        OR s.position_title ILIKE '%' || btrim(p_search) || '%'
        OR s.hrco_name ILIKE '%' || btrim(p_search) || '%'
      )
  ),
  counted AS (
    SELECT f.*, count(*) OVER () AS total_count
    FROM filtered f
  )
  SELECT
    c.hr_emploc_id,
    c.applicant_name,
    c.vcode,
    c.account_id,
    c.account_name,
    c.group_id,
    c.group_name,
    c.store_id,
    c.store_name,
    c.position_title,
    c.hr_status,
    c.status,
    c.emploc_no,
    c.employee_no,
    c.date_requested,
    c.created_at,
    c.hired_date,
    c.assignment_type,
    c.roving_assignment_id,
    c.aging_days,
    c.sla_breached,
    c.sla_status,
    c.sla_deadline,
    c.deficiency_summary,
    c.is_pending_deletion,
    c.row_capabilities,
    c.total_count
  FROM counted c
  ORDER BY
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'vcode'            THEN c.vcode END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'vcode'            THEN c.vcode END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'applicant_name'   THEN c.applicant_name END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'applicant_name'   THEN c.applicant_name END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'account_name'     THEN c.account_name END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'account_name'     THEN c.account_name END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'group_name'       THEN c.group_name END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'group_name'       THEN c.group_name END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'store_name'       THEN c.store_name END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'store_name'       THEN c.store_name END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'position_title'   THEN c.position_title END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'position_title'   THEN c.position_title END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'hr_status'        THEN c.hr_status END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'hr_status'        THEN c.hr_status END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'status'           THEN c.status END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'status'           THEN c.status END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'emploc_no'        THEN c.emploc_no END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'emploc_no'        THEN c.emploc_no END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'employee_no'      THEN c.employee_no END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'employee_no'      THEN c.employee_no END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'date_requested'   THEN c.date_requested END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'date_requested'   THEN c.date_requested END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'created_at'       THEN c.created_at END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'created_at'       THEN c.created_at END DESC NULLS LAST,
    CASE WHEN v_sort_dir = 'asc'  AND v_sort_by = 'aging_days'       THEN c.aging_days END ASC NULLS LAST,
    CASE WHEN v_sort_dir = 'desc' AND v_sort_by = 'aging_days'       THEN c.aging_days END DESC NULLS LAST,
    c.created_at DESC NULLS LAST
  LIMIT v_limit
  OFFSET v_offset;
END;
$function$

;

REVOKE ALL ON FUNCTION public.list_web_hr_emplocs(p_queue text, p_status text, p_deficiency text, p_sla_filter text, p_account_id uuid, p_group_id uuid, p_search text, p_limit integer, p_offset integer, p_sort_by text, p_sort_dir text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_web_hr_emplocs(p_queue text, p_status text, p_deficiency text, p_sla_filter text, p_account_id uuid, p_group_id uuid, p_search text, p_limit integer, p_offset integer, p_sort_by text, p_sort_dir text) TO authenticated;

-- Restoring revert_hr_emploc_to_pending (md5: 2ad3abff22899e812ed66f88af483a08)
CREATE OR REPLACE FUNCTION public.revert_hr_emploc_to_pending(p_hr_emploc_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor_profile_id uuid := public.get_my_profile_id();
  v_actor_name       text := public.get_my_full_name();
  v_reason           text := btrim(coalesce(p_reason, ''));
  v_emp              public.hr_emploc;
  v_pl               public.plantilla;
  v_old_employee_no  text;
  v_vacancy_id       uuid;
  v_vcode            text;
  v_active_plantilla_count int;
  v_req_headcount    int;
BEGIN
  IF v_reason = '' THEN
    RAISE EXCEPTION 'Reason for revert is required' USING ERRCODE = '22023';
  END IF;

  IF NOT (public.i_have_full_access() OR public.get_my_role() = 'Encoder' OR public.i_am_hr_dept()) THEN
    RAISE EXCEPTION 'forbidden: Super Admin, Data Team, or HR Personnel required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_emp FROM public.hr_emploc WHERE id = p_hr_emploc_id FOR UPDATE;
  IF NOT FOUND OR v_emp.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Record not found or archived' USING ERRCODE = 'P0002';
  END IF;

  v_old_employee_no := v_emp.employee_no;
  v_vacancy_id      := v_emp.vacancy_id;
  v_vcode           := v_emp.vcode;

  SELECT * INTO v_pl FROM public.plantilla
  WHERE hr_emploc_id = p_hr_emploc_id
     OR (v_old_employee_no IS NOT NULL AND employee_no = v_old_employee_no)
  LIMIT 1;

  IF v_pl.id IS NOT NULL THEN
    UPDATE public.plantilla
    SET is_deleted = true,
        status     = 'Deactivated',
        updated_at = now(),
        updated_by = v_actor_profile_id
    WHERE id = v_pl.id;

    UPDATE public.plantilla_store_links
    SET status = 'Backed Out',
        unlinked_at = now(),
        unlinked_by = v_actor_profile_id,
        updated_at = now(),
        updated_by = v_actor_profile_id
    WHERE plantilla_id = v_pl.id;

    UPDATE public.plantilla_slots
    SET slot_status = 'open',
        current_occupant_plantilla_id = NULL,
        updated_at = now()
    WHERE current_occupant_plantilla_id = v_pl.id;
  END IF;

  IF v_vcode IS NOT NULL THEN
    SELECT required_headcount INTO v_req_headcount
    FROM public.vacancies
    WHERE vcode = v_vcode AND deleted_at IS NULL
    LIMIT 1;

    SELECT count(*) INTO v_active_plantilla_count
    FROM public.plantilla
    WHERE vcode = v_vcode
      AND coalesce(is_deleted, false) = false
      AND status IN ('Active', 'On Leave');

    IF v_req_headcount IS NOT NULL AND coalesce(v_active_plantilla_count, 0) < v_req_headcount THEN
      UPDATE public.vacancies
      SET status = 'Open',
          updated_at = now(),
          updated_by = v_actor_profile_id
      WHERE vcode = v_vcode
        AND status IN ('Filled', 'Closed')
        AND coalesce(is_archived, false) = false
        AND deleted_at IS NULL;
    END IF;
  END IF;

  UPDATE public.hr_emploc
  SET employee_no            = NULL,
      emploc_no              = NULL,
      status                 = 'Pending Emploc',
      hr_status              = 'Pending',
      moved_to_plantilla_at  = NULL,
      moved_to_plantilla_by  = NULL,
      updated_at             = now(),
      updated_by             = v_actor_profile_id
  WHERE id = p_hr_emploc_id;

  PERFORM public.log_audit_event(
    'hr_emploc',
    'UPDATE',
    p_hr_emploc_id,
    jsonb_build_object('status', 'Moved to Plantilla', 'employee_no', v_old_employee_no),
    jsonb_build_object(
      'status', 'Pending Emploc',
      'employee_no', NULL,
      'reason', v_reason,
      'log_message', format('Reverted from Deployed to Pending and removed from Plantilla (Reason: %s) by %s', v_reason, v_actor_name)
    )
  );

  RETURN jsonb_build_object(
    'status', 'ok',
    'freed_employee_id', v_old_employee_no,
    'message', format('Reverted from Deployed to Pending and removed from Plantilla. Employee ID %s is now freed.', coalesce(v_old_employee_no, ''))
  );
END;
$function$

;

REVOKE ALL ON FUNCTION public.revert_hr_emploc_to_pending(p_hr_emploc_id uuid, p_reason text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.revert_hr_emploc_to_pending(p_hr_emploc_id uuid, p_reason text) TO authenticated;

-- Restoring update_deployed_employee_id (md5: d194f9b23b4a52344fe584e214be2b07)
CREATE OR REPLACE FUNCTION public.update_deployed_employee_id(p_hr_emploc_id uuid, p_new_employee_no text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor_profile_id uuid := public.get_my_profile_id();
  v_actor_name       text := public.get_my_full_name();
  v_clean_id         text := btrim(coalesce(p_new_employee_no, ''));
  v_reason           text := btrim(coalesce(p_reason, ''));
  v_emp              public.hr_emploc;
  v_old_id           text;
  v_check            jsonb;
BEGIN
  IF v_clean_id = '' THEN
    RAISE EXCEPTION 'New Employee ID is required' USING ERRCODE = '22023';
  END IF;
  IF v_reason = '' THEN
    RAISE EXCEPTION 'Reason for edit is required' USING ERRCODE = '22023';
  END IF;

  IF NOT (public.i_have_full_access() OR public.get_my_role() = 'Encoder' OR public.i_am_hr_dept()) THEN
    RAISE EXCEPTION 'forbidden: Super Admin, Data Team, or HR Personnel required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_emp FROM public.hr_emploc WHERE id = p_hr_emploc_id FOR UPDATE;
  IF NOT FOUND OR v_emp.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Record not found or archived' USING ERRCODE = 'P0002';
  END IF;

  v_old_id := v_emp.employee_no;

  -- Ecosystem uniqueness check (excluding current record)
  v_check := public.check_ecosystem_employee_id_unique(v_clean_id, p_hr_emploc_id);
  IF (v_check->>'is_unique')::boolean = false THEN
    RAISE EXCEPTION '%', (v_check->>'message') USING ERRCODE = '23505';
  END IF;

  -- Update hr_emploc
  UPDATE public.hr_emploc
  SET employee_no = v_clean_id,
      emploc_no   = v_clean_id,
      updated_at  = now(),
      updated_by  = v_actor_profile_id
  WHERE id = p_hr_emploc_id;

  -- Update plantilla row
  UPDATE public.plantilla
  SET employee_no = v_clean_id,
      emploc_no   = v_clean_id,
      updated_at  = now(),
      updated_by  = v_actor_profile_id
  WHERE hr_emploc_id = p_hr_emploc_id
     OR (v_old_id IS NOT NULL AND employee_no = v_old_id);

  -- Log Activity History Trail
  PERFORM public.log_audit_event(
    'hr_emploc',
    'UPDATE',
    p_hr_emploc_id,
    jsonb_build_object('employee_no', v_old_id),
    jsonb_build_object(
      'employee_no', v_clean_id,
      'reason', v_reason,
      'log_message', format('Updated Employee ID from %s to %s (Reason: %s) by %s', coalesce(v_old_id, 'None'), v_clean_id, v_reason, v_actor_name)
    )
  );

  RETURN jsonb_build_object(
    'status', 'ok',
    'old_id', v_old_id,
    'new_id', v_clean_id,
    'message', format('Updated Employee ID from %s to %s', coalesce(v_old_id, 'None'), v_clean_id)
  );
END;
$function$

;

REVOKE ALL ON FUNCTION public.update_deployed_employee_id(p_hr_emploc_id uuid, p_new_employee_no text, p_reason text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_deployed_employee_id(p_hr_emploc_id uuid, p_new_employee_no text, p_reason text) TO authenticated;

-- Restoring submit_correction (md5: 2ac30fe098c89b969cc16c70846a03dd)
CREATE OR REPLACE FUNCTION public.submit_correction(p_id uuid, p_ops_remark text)
 RETURNS hr_emploc
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old public.hr_emploc;
  v_new public.hr_emploc;
begin
  if not (i_am_ops() or i_have_full_access()) then
    raise exception 'forbidden: Ops role required' using errcode = '42501';
  end if;

  if coalesce(btrim(p_ops_remark),'') = '' then
    raise exception 'ops remark is required' using errcode = '22023';
  end if;

  select * into v_old
  from hr_emploc
  where id = p_id
  for update;

  if not found or v_old.deleted_at is not null then
    raise exception 'hr_emploc % not found or archived', p_id using errcode = 'P0002';
  end if;

  if v_old.hr_status <> 'For Correction' then
    raise exception 'cannot submit correction: hr_status is %', v_old.hr_status using errcode = '22023';
  end if;

  update hr_emploc
     set hr_status   = 'Pending',
         status      = 'Pending Emploc',
         ops_remarks = p_ops_remark,
         last_correction_submitter_user_id = get_my_profile_id(),
         updated_at  = now(),
         updated_by  = get_my_profile_id()
   where id = p_id
   returning * into v_new;

  perform log_audit_event('hr_emploc','UPDATE', p_id, to_jsonb(v_old), to_jsonb(v_new));
  return v_new;
end;
$function$

;

REVOKE ALL ON FUNCTION public.submit_correction(p_id uuid, p_ops_remark text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_correction(p_id uuid, p_ops_remark text) TO authenticated;

-- Restoring submit_hrco_correction_update (md5: 78c981827c3f62f26d1a01a93a048af5)
CREATE OR REPLACE FUNCTION public.submit_hrco_correction_update(p_correction_request_id uuid, p_hrco_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- PENDING DELETION LOCK
  IF EXISTS (
    SELECT 1 FROM public.hr_emploc_deletion_requests
    WHERE hr_emploc_id = p_correction_request_id AND status = 'Pending'
  ) THEN
    RAISE EXCEPTION 'action locked: a pending deletion request exists for this record'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.hr_emploc
  SET ops_remarks = nullif(trim(p_hrco_notes), ''),
      hr_status   = 'For Review',
      updated_at  = now()
  WHERE id = p_correction_request_id
    AND hr_status = 'For Correction';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Correction request not found or not in For Correction status'
      USING ERRCODE = 'P0002';
  END IF;
END;
$function$

;

REVOKE ALL ON FUNCTION public.submit_hrco_correction_update(p_correction_request_id uuid, p_hrco_notes text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_hrco_correction_update(p_correction_request_id uuid, p_hrco_notes text) TO authenticated;

-- Restoring mark_for_correction (md5: f79bbd799cb11aa46fca738ceb3499f4)
CREATE OR REPLACE FUNCTION public.mark_for_correction(p_id uuid, p_issues jsonb, p_hr_remarks text DEFAULT NULL::text)
 RETURNS hr_emploc
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old     public.hr_emploc;
  v_new     public.hr_emploc;
  v_issue   jsonb;
  v_code    text;
  v_comment text;
  v_needs_comment boolean;
BEGIN
  IF NOT (i_am_hr_dept() OR i_have_full_access()) THEN
    RAISE EXCEPTION 'forbidden: HR Dept role required' USING ERRCODE = '42501';
  END IF;

  IF p_issues IS NULL
     OR jsonb_typeof(p_issues) <> 'array'
     OR jsonb_array_length(p_issues) = 0 THEN
    RAISE EXCEPTION 'p_issues must be a non-empty JSONB array of {code, comment} objects'
      USING ERRCODE = '22023';
  END IF;

  FOR v_issue IN SELECT * FROM jsonb_array_elements(p_issues) LOOP
    v_code    := NULLIF(BTRIM(COALESCE(v_issue->>'code', '')), '');
    v_comment := BTRIM(COALESCE(v_issue->>'comment', ''));

    IF v_code IS NULL THEN
      RAISE EXCEPTION 'each issue entry must include a non-empty code'
        USING ERRCODE = '22023';
    END IF;

    SELECT requires_comment
      INTO v_needs_comment
      FROM hr_emploc_issue_types
     WHERE code = v_code AND is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'unknown or inactive issue code: %', v_code
        USING ERRCODE = '22023';
    END IF;

    IF v_needs_comment AND v_comment = '' THEN
      RAISE EXCEPTION 'comment is required for issue code: %', v_code
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  SELECT * INTO v_old FROM hr_emploc WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_old.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'hr_emploc % not found or archived', p_id USING ERRCODE = 'P0002';
  END IF;

  UPDATE hr_emploc
     SET hr_status            = 'For Correction',
         status               = 'For Compliance',
         correction_reason    = p_issues,
         hr_remarks           = COALESCE(
                                  NULLIF(BTRIM(COALESCE(p_hr_remarks, '')), ''),
                                  hr_remarks
                                ),
         hr_reviewed_at       = now(),
         hr_reviewed_by       = get_my_full_name(),
         hr_reviewed_by_user_id = get_my_profile_id(),
         updated_at           = now(),
         updated_by           = get_my_profile_id()
   WHERE id = p_id
   RETURNING * INTO v_new;

  PERFORM log_audit_event('hr_emploc', 'UPDATE', p_id, to_jsonb(v_old), to_jsonb(v_new));
  RETURN v_new;
END;
$function$

;

REVOKE ALL ON FUNCTION public.mark_for_correction(p_id uuid, p_issues jsonb, p_hr_remarks text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.mark_for_correction(p_id uuid, p_issues jsonb, p_hr_remarks text) TO authenticated;

-- Restoring tag_web_hr_emploc_deficiency (md5: 6be585453dceb76b8eb4b1ccf50e0231)
CREATE OR REPLACE FUNCTION public.tag_web_hr_emploc_deficiency(p_hr_emploc_id uuid, p_deficiencies jsonb, p_remarks text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auth_uid      uuid    := auth.uid();
  v_profile_id    uuid;
  v_role_name     text;
  v_role_level    integer;
  v_old           public.hr_emploc;
  v_new           public.hr_emploc;
  v_issue         jsonb;
  v_code          text;
  v_comment       text;
  v_needs_comment boolean;
BEGIN

  -- ----------------------------------------------------------------
  -- 1. Auth guard — fail closed, no session = no access
  -- ----------------------------------------------------------------
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated: deficiency tagging requires a valid session'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 2. Profile resolution — active, non-archived profile + role
  -- ----------------------------------------------------------------
  SELECT up.id, r.role_name, r.role_level
  INTO   v_profile_id, v_role_name, v_role_level
  FROM   public.users_profile up
  JOIN   public.roles r ON r.id = up.role_id
  WHERE  up.auth_user_id = v_auth_uid
    AND  up.is_active    = TRUE
    AND  up.archived_at  IS NULL
  ORDER  BY up.created_at DESC
  LIMIT  1;

  IF v_profile_id IS NULL OR COALESCE(v_role_level, 0) <= 0 THEN
    RAISE EXCEPTION 'forbidden: caller profile is inactive or not found'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 3. RBAC capability guard
  --    Mirrors mark_for_correction: HR Dept (hrPersonnel) or full access
  --    (headAdmin / superAdmin). All other roles are denied.
  -- ----------------------------------------------------------------
  IF NOT (public.i_am_hr_dept() OR public.i_have_full_access()) THEN
    RAISE EXCEPTION 'forbidden: HR Personnel or Admin role required for deficiency tagging'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 4. Validate deficiencies input
  --    Must be a non-empty JSONB array of {code, comment} objects.
  --    Every code must exist and be active in hr_emploc_issue_types.
  --    Codes that require_comment must supply a non-empty comment.
  -- ----------------------------------------------------------------
  IF p_deficiencies IS NULL
     OR jsonb_typeof(p_deficiencies) <> 'array'
     OR jsonb_array_length(p_deficiencies) = 0
  THEN
    RAISE EXCEPTION 'p_deficiencies must be a non-empty JSONB array of {code, comment} objects'
      USING ERRCODE = '22023';
  END IF;

  FOR v_issue IN SELECT * FROM jsonb_array_elements(p_deficiencies) LOOP
    v_code    := NULLIF(BTRIM(COALESCE(v_issue->>'code',    '')), '');
    v_comment :=        BTRIM(COALESCE(v_issue->>'comment', ''));

    IF v_code IS NULL THEN
      RAISE EXCEPTION 'each deficiency entry must include a non-empty code'
        USING ERRCODE = '22023';
    END IF;

    SELECT requires_comment
    INTO   v_needs_comment
    FROM   public.hr_emploc_issue_types
    WHERE  code      = v_code
      AND  is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'unknown or inactive deficiency code: %', v_code
        USING ERRCODE = '22023';
    END IF;

    IF v_needs_comment AND v_comment = '' THEN
      RAISE EXCEPTION 'comment is required for deficiency code: %', v_code
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- ----------------------------------------------------------------
  -- 5. Lock and fetch the record
  --    FOR UPDATE prevents concurrent state changes during validation.
  -- ----------------------------------------------------------------
  SELECT * INTO v_old
  FROM   public.hr_emploc
  WHERE  id = p_hr_emploc_id
  FOR    UPDATE;

  IF NOT FOUND OR v_old.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'forbidden: hr_emploc record not found or archived'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 6. Scope gate — non-global callers (role_level < 90) must have
  --    an account/group assignment that covers the record's account.
  --    Mirrors scoping logic from list_web_hr_emplocs and
  --    get_web_hr_emploc_detail for consistency.
  -- ----------------------------------------------------------------
  IF COALESCE(v_role_level, 0) < 90 THEN
    IF NOT (
      v_old.account = ANY (public.get_my_allowed_accounts())
      OR EXISTS (
        SELECT 1 FROM public.user_scopes us
        WHERE  us.user_id    = v_profile_id
          AND  us.account_id = v_old.account_id
      )
      OR EXISTS (
        SELECT 1
        FROM   public.user_scopes us
        JOIN   public.accounts   ac ON ac.id = v_old.account_id
        WHERE  us.user_id    = v_profile_id
          AND  us.account_id IS NULL
          AND  us.group_id   = ac.group_id
      )
      OR EXISTS (
        SELECT 1
        FROM   public.users_profile up_f
        JOIN   public.accounts      ac ON ac.id = v_old.account_id
        WHERE  up_f.id = v_profile_id
          AND  NOT EXISTS (
            SELECT 1 FROM public.user_scopes us_any
            WHERE  us_any.user_id = v_profile_id
              AND  (us_any.group_id IS NOT NULL OR us_any.account_id IS NOT NULL)
          )
          AND  (up_f.account_id = v_old.account_id OR up_f.group_id = ac.group_id)
      )
    ) THEN
      RAISE EXCEPTION 'forbidden: hr_emploc record is outside your assigned scope'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- ----------------------------------------------------------------
  -- 7. Terminal state guard
  --    Records already moved to Plantilla must never be modified.
  -- ----------------------------------------------------------------
  IF v_old.moved_to_plantilla_at IS NOT NULL
     OR v_old.status = 'Moved to Plantilla'
  THEN
    RAISE EXCEPTION 'action not allowed: employee has already been moved to Plantilla'
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 8. Pending deletion lock
  --    Mirrors trg_hr_emploc_pending_deletion_lock and the explicit
  --    guard in assign_hr_emploc_number / submit_hrco_correction_update.
  -- ----------------------------------------------------------------
  IF EXISTS (
    SELECT 1
    FROM   public.hr_emploc_deletion_requests
    WHERE  hr_emploc_id = p_hr_emploc_id
      AND  status       = 'Pending'
  ) THEN
    RAISE EXCEPTION 'action locked: a pending deletion request exists for this record'
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 9. Complete state guard
  --    Complete = employee number assigned and ready for Plantilla.
  --    Deficiency tagging on a Complete record is a logical conflict.
  -- ----------------------------------------------------------------
  IF v_old.hr_status = 'Complete' THEN
    RAISE EXCEPTION 'action not allowed: hr_emploc is already in Complete state (employee number assigned)'
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 10. Apply deficiency tagging
  --     Mirrors mark_for_correction semantics:
  --       correction_reason ← p_deficiencies (JSONB array)
  --       hr_status         ← 'For Correction'
  --       status            ← 'For Compliance'
  --       hr_remarks        ← p_remarks if non-empty, else preserve existing
  --       audit fields      ← stamped
  -- ----------------------------------------------------------------
  UPDATE public.hr_emploc
  SET    correction_reason = p_deficiencies,
         hr_status         = 'For Correction',
         status            = 'For Compliance',
         hr_remarks        = COALESCE(
                               NULLIF(BTRIM(COALESCE(p_remarks, '')), ''),
                               hr_remarks
                             ),
         hr_reviewed_at    = now(),
         hr_reviewed_by    = public.get_my_full_name(),
         updated_at        = now(),
         updated_by        = v_profile_id
  WHERE  id = p_hr_emploc_id
  RETURNING * INTO v_new;

  -- ----------------------------------------------------------------
  -- 11. Audit trail via existing log_audit_event helper
  -- ----------------------------------------------------------------
  PERFORM public.log_audit_event(
    'hr_emploc',
    'UPDATE',
    p_hr_emploc_id,
    to_jsonb(v_old),
    to_jsonb(v_new)
  );

  -- ----------------------------------------------------------------
  -- 12. Return JSONB result envelope
  -- ----------------------------------------------------------------
  RETURN jsonb_build_object(
    'status',           'ok',
    'hr_emploc_id',     v_new.id,
    'hr_status',        v_new.hr_status,
    'deficiency_count', jsonb_array_length(p_deficiencies),
    'tagged_by',        public.get_my_full_name(),
    'tagged_at',        now()
  );

END;
$function$

;

REVOKE ALL ON FUNCTION public.tag_web_hr_emploc_deficiency(p_hr_emploc_id uuid, p_deficiencies jsonb, p_remarks text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.tag_web_hr_emploc_deficiency(p_hr_emploc_id uuid, p_deficiencies jsonb, p_remarks text) TO authenticated;

-- Restoring review_web_hr_emploc_correction (md5: a4d89e8b09ceabac69ff65c609ff1089)
CREATE OR REPLACE FUNCTION public.review_web_hr_emploc_correction(p_hr_emploc_id uuid, p_decision text, p_resolved_keys jsonb, p_remarks text DEFAULT NULL::text, p_employee_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auth_uid                   uuid    := auth.uid();
  v_profile_id                 uuid;
  v_role_level                 integer;
  v_old                        public.hr_emploc;
  v_new                        public.hr_emploc;
  v_existing_codes             text[];
  v_resolved_codes             text[];
  v_residual_codes             text[];
  v_residual_correction_reason jsonb;
BEGIN

  -- ----------------------------------------------------------------
  -- 1. Auth guard — fail closed, no session = no access
  -- ----------------------------------------------------------------
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated: correction review requires a valid session'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 2. Profile resolution — active, non-archived profile + role level
  -- ----------------------------------------------------------------
  SELECT up.id, r.role_level
  INTO   v_profile_id, v_role_level
  FROM   public.users_profile up
  JOIN   public.roles r ON r.id = up.role_id
  WHERE  up.auth_user_id = v_auth_uid
    AND  up.is_active    = TRUE
    AND  up.archived_at  IS NULL
  ORDER  BY up.created_at DESC
  LIMIT  1;

  IF v_profile_id IS NULL OR COALESCE(v_role_level, 0) <= 0 THEN
    RAISE EXCEPTION 'forbidden: caller profile is inactive or not found'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 3. RBAC capability guard
  --    Mirrors approve_correction_request: HR Dept (hrPersonnel) or
  --    full access (headAdmin / superAdmin). All other roles denied.
  -- ----------------------------------------------------------------
  IF NOT (public.i_am_hr_dept() OR public.i_have_full_access()) THEN
    RAISE EXCEPTION 'forbidden: HR Personnel or Admin role required for correction review'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 4. Decision validation
  -- ----------------------------------------------------------------
  IF p_decision NOT IN ('approve', 'return') THEN
    RAISE EXCEPTION 'invalid decision: must be ''approve'' or ''return'''
      USING ERRCODE = '22023';
  END IF;

  -- ----------------------------------------------------------------
  -- 5. Lock and fetch the record
  --    FOR UPDATE prevents concurrent state changes during validation.
  -- ----------------------------------------------------------------
  SELECT * INTO v_old
  FROM   public.hr_emploc
  WHERE  id = p_hr_emploc_id
  FOR    UPDATE;

  IF NOT FOUND OR v_old.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'forbidden: hr_emploc record not found or archived'
      USING ERRCODE = '42501';
  END IF;

  -- ----------------------------------------------------------------
  -- 6. Scope gate — non-global callers (role_level < 90) must have
  --    an account/group assignment that covers the record's account.
  -- ----------------------------------------------------------------
  IF COALESCE(v_role_level, 0) < 90 THEN
    IF NOT (
      v_old.account = ANY (public.get_my_allowed_accounts())
      OR EXISTS (
        SELECT 1 FROM public.user_scopes us
        WHERE  us.user_id    = v_profile_id
          AND  us.account_id = v_old.account_id
      )
      OR EXISTS (
        SELECT 1
        FROM   public.user_scopes us
        JOIN   public.accounts   ac ON ac.id = v_old.account_id
        WHERE  us.user_id    = v_profile_id
          AND  us.account_id IS NULL
          AND  us.group_id   = ac.group_id
      )
      OR EXISTS (
        SELECT 1
        FROM   public.users_profile up_f
        JOIN   public.accounts      ac ON ac.id = v_old.account_id
        WHERE  up_f.id = v_profile_id
          AND  NOT EXISTS (
            SELECT 1 FROM public.user_scopes us_any
            WHERE  us_any.user_id = v_profile_id
              AND  (us_any.group_id IS NOT NULL OR us_any.account_id IS NOT NULL)
          )
          AND  (up_f.account_id = v_old.account_id OR up_f.group_id = ac.group_id)
      )
    ) THEN
      RAISE EXCEPTION 'forbidden: hr_emploc record is outside your assigned scope'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- ----------------------------------------------------------------
  -- 7. Terminal state guard
  -- ----------------------------------------------------------------
  IF v_old.moved_to_plantilla_at IS NOT NULL
     OR v_old.status    = 'Moved to Plantilla'
     OR v_old.hr_status = 'Transferred'
  THEN
    RAISE EXCEPTION 'action not allowed: employee has already been moved to Plantilla'
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 8. Pending deletion lock
  -- ----------------------------------------------------------------
  IF EXISTS (
    SELECT 1
    FROM   public.hr_emploc_deletion_requests
    WHERE  hr_emploc_id = p_hr_emploc_id
      AND  status       = 'Pending'
  ) THEN
    RAISE EXCEPTION 'action locked: a pending deletion request exists for this record'
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 9. hr_status guard — must be in For Review
  -- ----------------------------------------------------------------
  IF v_old.hr_status <> 'For Review' THEN
    RAISE EXCEPTION 'action not allowed: hr_status is "%" — expected "For Review"',
      v_old.hr_status
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 10. status guard — must be Pending Emploc
  -- ----------------------------------------------------------------
  IF v_old.status <> 'Pending Emploc' THEN
    RAISE EXCEPTION 'action not allowed: status is "%" — expected "Pending Emploc"',
      v_old.status
      USING ERRCODE = 'P0001';
  END IF;

  -- ----------------------------------------------------------------
  -- 11. Compute existing, resolved, and residual correction codes
  -- ----------------------------------------------------------------
  SELECT COALESCE(array_agg(elem->>'code'), '{}')
  INTO   v_existing_codes
  FROM   jsonb_array_elements(
           CASE WHEN jsonb_typeof(v_old.correction_reason) = 'array'
                THEN v_old.correction_reason
                ELSE '[]'::jsonb
           END
         ) elem
  WHERE  NULLIF(elem->>'code', '') IS NOT NULL;

  SELECT COALESCE(array_agg(v), '{}')
  INTO   v_resolved_codes
  FROM   jsonb_array_elements_text(COALESCE(p_resolved_keys, '[]'::jsonb)) v;

  SELECT COALESCE(array_agg(c), '{}')
  INTO   v_residual_codes
  FROM   unnest(v_existing_codes) c
  WHERE  NOT (c = ANY(v_resolved_codes));

  -- ----------------------------------------------------------------
  -- 12a. APPROVE path
  -- ----------------------------------------------------------------
  IF p_decision = 'approve' THEN

    -- All existing correction codes must appear in p_resolved_keys.
    IF COALESCE(array_length(v_residual_codes, 1), 0) > 0 THEN
      RAISE EXCEPTION
        'approve requires all existing correction keys to be resolved; % unresolved key(s) remain: %',
        COALESCE(array_length(v_residual_codes, 1), 0),
        array_to_string(v_residual_codes, ', ')
        USING ERRCODE = 'P0001';
    END IF;

    -- Update correction_reason to NULL and record optional approval remarks
    UPDATE public.hr_emploc
    SET    correction_reason = NULL,
           hr_remarks        = COALESCE(
                                 NULLIF(BTRIM(COALESCE(p_remarks, '')), ''),
                                 hr_remarks
                               )
    WHERE  id = p_hr_emploc_id;

    -- Delegate validation and assignment to internal core function
    v_new := public._assign_hr_emploc_number_core(p_hr_emploc_id, p_employee_no);

    RETURN jsonb_build_object(
      'status',        'ok',
      'hr_emploc_id',  v_new.id,
      'decision',      'approve',
      'hr_status',     v_new.hr_status,
      'employee_no',   v_new.employee_no,
      'resolved_keys', to_jsonb(v_resolved_codes),
      'residual_keys', to_jsonb(ARRAY[]::text[]),
      'reviewed_by',   public.get_my_full_name(),
      'reviewed_at',   now()
    );

  END IF;

  -- ----------------------------------------------------------------
  -- 12b. RETURN path
  -- ----------------------------------------------------------------

  -- Require at least one residual key or a non-empty remark.
  IF COALESCE(array_length(v_residual_codes, 1), 0) = 0
     AND NULLIF(BTRIM(COALESCE(p_remarks, '')), '') IS NULL
  THEN
    RAISE EXCEPTION
      'return requires at least one unresolved correction key or a non-empty remark'
      USING ERRCODE = '22023';
  END IF;

  -- Build residual correction_reason: keep only items whose code is unresolved.
  IF COALESCE(array_length(v_residual_codes, 1), 0) > 0 THEN
    SELECT jsonb_agg(elem)
    INTO   v_residual_correction_reason
    FROM   jsonb_array_elements(
             CASE WHEN jsonb_typeof(v_old.correction_reason) = 'array'
                  THEN v_old.correction_reason
                  ELSE '[]'::jsonb
             END
           ) elem
    WHERE  elem->>'code' = ANY(v_residual_codes);
  ELSE
    -- All codes resolved but remark present: correction reason is cleared.
    v_residual_correction_reason := NULL;
  END IF;

  UPDATE public.hr_emploc
  SET    hr_status         = 'For Correction',
         correction_reason = v_residual_correction_reason,
         hr_remarks        = COALESCE(
                               NULLIF(BTRIM(COALESCE(p_remarks, '')), ''),
                               hr_remarks
                             ),
         hr_reviewed_by    = public.get_my_full_name(),
         hr_reviewed_at    = now(),
         updated_at        = now(),
         updated_by        = v_profile_id
  WHERE  id = p_hr_emploc_id
  RETURNING * INTO v_new;

  PERFORM public.log_audit_event(
    'hr_emploc',
    'UPDATE',
    p_hr_emploc_id,
    to_jsonb(v_old),
    to_jsonb(v_new)
  );

  RETURN jsonb_build_object(
    'status',        'ok',
    'hr_emploc_id',  v_new.id,
    'decision',      'return',
    'hr_status',     v_new.hr_status,
    'resolved_keys', to_jsonb(v_resolved_codes),
    'residual_keys', to_jsonb(v_residual_codes),
    'reviewed_by',   public.get_my_full_name(),
    'reviewed_at',   now()
  );

END;
$function$

;

REVOKE ALL ON FUNCTION public.review_web_hr_emploc_correction(p_hr_emploc_id uuid, p_decision text, p_resolved_keys jsonb, p_remarks text, p_employee_no text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_web_hr_emploc_correction(p_hr_emploc_id uuid, p_decision text, p_resolved_keys jsonb, p_remarks text, p_employee_no text) TO authenticated;

-- Restoring assign_hr_emploc_number (md5: a9b5110814b91841d8de9e606430c8f1)
CREATE OR REPLACE FUNCTION public.assign_hr_emploc_number(p_id uuid, p_employee_no text)
 RETURNS hr_emploc
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old   public.hr_emploc;
  v_new   public.hr_emploc;
  v_clean text := nullif(btrim(p_employee_no),'');
BEGIN
  IF NOT (i_am_hr_dept() OR is_super_admin()) THEN
    RAISE EXCEPTION 'forbidden: HR Dept role required' USING ERRCODE = '42501';
  END IF;

  IF v_clean IS NULL THEN
    RAISE EXCEPTION 'employee_no is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_old FROM hr_emploc WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_old.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'hr_emploc % not found or archived', p_id USING ERRCODE = 'P0002';
  END IF;

  -- PENDING DELETION LOCK
  IF EXISTS (
    SELECT 1 FROM public.hr_emploc_deletion_requests
    WHERE hr_emploc_id = p_id AND status = 'Pending'
  ) THEN
    RAISE EXCEPTION 'action locked: a pending deletion request exists for this record'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1 FROM hr_emploc
    WHERE employee_no = v_clean AND id <> p_id
      AND deleted_at IS NULL
      AND status NOT IN ('Backout','Moved to Plantilla')
  ) THEN
    RAISE EXCEPTION 'employee_no % already in use on active hr_emploc', v_clean USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1 FROM plantilla
    WHERE employee_no = v_clean
      AND is_deleted = false
      AND status IN ('Active','For Deactivation','On Leave')
  ) THEN
    RAISE EXCEPTION 'employee_no % already exists in active plantilla', v_clean USING ERRCODE = '23505';
  END IF;

  UPDATE hr_emploc
  SET employee_no            = v_clean,
      emploc_no              = v_clean,
      hr_status              = 'Complete',
      status                 = 'Ready for Plantilla',
      hr_reviewed_at         = now(),
      hr_reviewed_by         = get_my_full_name(),
      hr_reviewed_by_user_id = get_my_profile_id(),
      updated_at             = now(),
      updated_by             = get_my_profile_id()
  WHERE id = p_id
  RETURNING * INTO v_new;

  PERFORM log_audit_event('hr_emploc','UPDATE', p_id, to_jsonb(v_old), to_jsonb(v_new));
  RETURN v_new;
END;
$function$

;

REVOKE ALL ON FUNCTION public.assign_hr_emploc_number(p_id uuid, p_employee_no text) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.assign_hr_emploc_number(p_id uuid, p_employee_no text) TO authenticated;

-- Restoring move_to_plantilla (md5: d44fa3a58b8af3b3b2c325222d989347)
CREATE OR REPLACE FUNCTION public.move_to_plantilla(p_id uuid)
 RETURNS plantilla
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_emp             public.hr_emploc;
  v_pl              public.plantilla;
  v_app             public.applicants;
  v_formatted_name  text;
  v_actor           uuid := get_my_profile_id();
  v_is_pool         boolean := false;
  v_pool_type_id    uuid;
  v_home_account_id uuid;
  v_home_acct       public.accounts;
  v_slot_id         uuid := NULL;
  v_slot_auth       jsonb;
  v_pool_slot_id    uuid := NULL;
BEGIN
  -- Data Team = Encoder + Head Admin + Super Admin
  IF NOT (i_have_full_access() OR get_my_role() = 'Encoder') THEN
    RAISE EXCEPTION 'forbidden: Data Team role required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_emp FROM hr_emploc WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_emp.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'hr_emploc % not found or archived', p_id USING ERRCODE = 'P0002';
  END IF;
  IF v_emp.status <> 'Ready for Plantilla' THEN
    RAISE EXCEPTION 'cannot move: status is "%", expected "Ready for Plantilla"', v_emp.status
      USING ERRCODE = '22023';
  END IF;
  IF v_emp.employee_no IS NULL THEN
    RAISE EXCEPTION 'cannot move: employee_no is null' USING ERRCODE = '22023';
  END IF;

  -- Guard A: hr_emploc_id already active in plantilla
  IF EXISTS (
    SELECT 1
      FROM public.plantilla
     WHERE hr_emploc_id              = p_id
       AND COALESCE(is_deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'hr_emploc % already moved to plantilla', p_id USING ERRCODE = '23505';
  END IF;

  -- Guard B: moved_to_plantilla_at already stamped
  IF v_emp.moved_to_plantilla_at IS NOT NULL THEN
    RAISE EXCEPTION
      'hr_emploc % already has moved_to_plantilla_at set', p_id USING ERRCODE = '23505';
  END IF;

  -- Fetch structured applicant name parts if available
  IF v_emp.applicant_id IS NOT NULL THEN
    SELECT * INTO v_app FROM public.applicants WHERE id = v_emp.applicant_id;
  END IF;

  -- Format canonical employee name: LAST, FIRST MIDDLE
  IF v_app.last_name IS NOT NULL AND v_app.first_name IS NOT NULL THEN
    v_formatted_name := v_app.last_name || ', ' || v_app.first_name || COALESCE(' ' || NULLIF(btrim(v_app.middle_name), ''), '');
  ELSE
    v_formatted_name := COALESCE(v_emp.employee_name_snapshot, v_emp.applicant_name);
  END IF;

  -- Detect pool vacancy
  IF v_emp.vacancy_id IS NOT NULL THEN
    SELECT v.is_pool_vacancy, v.pool_type_id, v.home_account_id
      INTO v_is_pool, v_pool_type_id, v_home_account_id
      FROM vacancies v
     WHERE v.id = v_emp.vacancy_id;
  END IF;
  v_is_pool := COALESCE(v_is_pool, false);

  -- ── 1. ATOMIC SLOT SELECTION & RESERVATION (Stationary non-pool non-roving path) ──
  IF NOT v_is_pool AND COALESCE(v_emp.assignment_type, 'Stationary') <> 'Roving' AND v_emp.coverage_slot_id IS NULL THEN
    -- Atomic slot selection using FOR UPDATE SKIP LOCKED
    SELECT id INTO v_slot_id
    FROM public.plantilla_slots
    WHERE legacy_vcode = v_emp.vcode
      AND slot_status = 'open'
    ORDER BY created_at ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    -- 2. HANDLE NO AVAILABLE SLOT
    IF v_slot_id IS NULL THEN
      -- Fallback: check if hr_emploc already holds a reserved slot in open/hr_processing state
      IF v_emp.slot_id IS NOT NULL THEN
        SELECT id INTO v_slot_id
        FROM public.plantilla_slots
        WHERE id = v_emp.slot_id
          AND slot_status IN ('open', 'hr_processing')
        FOR UPDATE SKIP LOCKED;
      END IF;

      IF v_slot_id IS NULL THEN
        RAISE EXCEPTION 'No available headcount for this VCode.' USING ERRCODE = '22023';
      END IF;
    END IF;

    -- 3. TRANSITION SLOT STATE (RESERVE FIRST)
    -- ohm#7k2d9f4a: routed through fn_set_slot_status (slot authority)
    v_slot_auth := public.fn_set_slot_status(
      p_slot_id      => v_slot_id,
      p_new_status   => 'hr_processing',
      p_reason_code  => NULL,
      p_performed_by => v_actor,
      p_remarks      => 'move_to_plantilla: slot reserved for hr_emploc ' || p_id::text
    );
    IF (v_slot_auth->>'status') NOT IN ('ok', 'no_op') THEN
      RAISE EXCEPTION 'move_to_plantilla: slot % reservation blocked: %',
        v_slot_id, COALESCE(v_slot_auth->>'blocked_reason', 'unknown')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  -- ── 4. INSERT INTO PLANTILLA ───────────────────────────────────────────────

  -- ── POOL PATH ───────────────────────────────────────────────────────────────
  IF v_is_pool THEN

    IF v_home_account_id IS NULL THEN
      RAISE EXCEPTION 'pool vacancy % has no home_account_id — cannot route to pool',
        v_emp.vcode USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_home_acct FROM accounts WHERE id = v_home_account_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'home account % not found', v_home_account_id USING ERRCODE = 'P0002';
    END IF;

    IF EXISTS (
      SELECT 1 FROM plantilla
       WHERE employee_no = v_emp.employee_no
         AND account_id  = v_home_account_id
         AND is_deleted  = false
         AND status IN ('Active', 'For Deactivation', 'On Leave')
    ) THEN
      RAISE EXCEPTION
        'pool plantilla already has active record for employee_no % under home account',
        v_emp.employee_no USING ERRCODE = '23505';
    END IF;

    -- Prefer the slot reserved for this hr_emploc row at Confirmed Onboard
    IF v_emp.pool_slot_id IS NOT NULL THEN
      SELECT id INTO v_pool_slot_id
        FROM public.workforce_pool_slots
       WHERE id = v_emp.pool_slot_id
         AND deleted_at IS NULL
         AND is_active   = true
         AND status IN ('open', 'hr_processing')
       FOR UPDATE SKIP LOCKED;
    END IF;

    IF v_pool_slot_id IS NULL THEN
      SELECT id INTO v_pool_slot_id
        FROM public.workforce_pool_slots
       WHERE vcode = v_emp.vcode
         AND deleted_at IS NULL
         AND is_active = true
         AND status = 'open'
       ORDER BY created_at ASC
       LIMIT 1
       FOR UPDATE SKIP LOCKED;
    END IF;

    IF v_pool_slot_id IS NULL THEN
      RAISE EXCEPTION 'No available pool slot for VCode %.', v_emp.vcode USING ERRCODE = '22023';
    END IF;

    INSERT INTO plantilla (
      account,              account_id,
      store_id,             store_name,
      position,             position_id,
      employee_no,          emploc_no,
      employee_name,        employee_name_snapshot,
      first_name,           middle_name,             last_name,
      civil_status,         date_of_birth,
      sss_no,               philhealth_no,          pagibig_no,
      date_hired,           vacancy_id,              vacancy_code_snapshot,
      vcode,
      hrco_name,            hrco_user_id_snapshot,
      om_user_id_snapshot,  atl_user_id_snapshot,
      area,                 area_name_snapshot,
      hr_emploc_id,
      is_pool_employee,     pool_type_id,
      requesting_account,   requesting_account_id,   requesting_store_id,
      status,               tagged_at,
      moved_by_user_id,     created_by,              updated_by,
      created_at,           updated_at
    )
    VALUES (
      v_home_acct.account_name, v_home_acct.id,
      NULL, NULL,
      v_emp.position,           v_emp.position_id_snapshot,
      v_emp.employee_no,        v_emp.employee_no,
      v_formatted_name,         v_formatted_name,
      v_app.first_name,         v_app.middle_name,       v_app.last_name,
      v_emp.civil_status_snapshot, v_emp.birthdate_snapshot,
      v_emp.sss_snapshot,       v_emp.philhealth_snapshot,    v_emp.pagibig_snapshot,
      v_emp.hired_date,         v_emp.vacancy_id,             v_emp.vacancy_code_snapshot,
      v_emp.vcode,
      v_emp.hrco_name,          v_emp.hrco_user_id_snapshot,
      v_emp.om_user_id_snapshot, v_emp.atl_user_id_snapshot,
      v_emp.area_name_snapshot,  v_emp.area_name_snapshot,
      v_emp.id,
      true,                     v_pool_type_id,
      v_emp.account,            v_emp.account_id,             v_emp.store_id,
      'Active',                 CURRENT_DATE,
      v_actor, v_actor, v_actor,
      NOW(), NOW()
    )
    RETURNING * INTO v_pl;

    IF v_emp.vacancy_id IS NOT NULL THEN
      UPDATE vacancies
         SET status     = 'Filled',
             updated_at = NOW(),
             updated_by = v_actor
       WHERE id = v_emp.vacancy_id
         AND NOT EXISTS (
           SELECT 1 FROM public.workforce_pool_slots wps
           WHERE wps.vcode = v_emp.vcode
             AND wps.deleted_at IS NULL
             AND wps.is_active = true
             AND wps.status IN ('open', 'hr_processing')
         );
    END IF;

    UPDATE public.vacancies
       SET status     = 'Filled',
           updated_at = NOW(),
           updated_by = v_actor
     WHERE vcode      = v_emp.vcode
       AND status     IN ('Open', 'For Sourcing')
       AND COALESCE(is_archived, false) = false
       AND deleted_at IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.workforce_pool_slots wps
         WHERE wps.vcode = v_emp.vcode
           AND wps.deleted_at IS NULL
           AND wps.is_active = true
           AND wps.status IN ('open', 'hr_processing')
       );

    UPDATE public.workforce_pool_slots
       SET status               = 'filled',
           occupant_employee_id = v_pl.id,
           updated_at           = NOW()
     WHERE id = v_pool_slot_id;

  -- ── ROVING PATH ─────────────────────────────────────────────────────────────
  ELSIF v_emp.assignment_type = 'Roving' THEN

    IF EXISTS (
      SELECT 1 FROM plantilla
       WHERE roving_assignment_id = v_emp.roving_assignment_id
         AND is_deleted = false
    ) THEN
      RAISE EXCEPTION
        'roving plantilla master already exists for roving_assignment_id %. '
        'Use link_late_store_to_plantilla for new store additions.',
        v_emp.roving_assignment_id USING ERRCODE = '23505';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM hr_emploc_store_links
       WHERE hr_emploc_id = p_id
         AND status       = 'Confirmed'
         AND deleted_at   IS NULL
    ) THEN
      RAISE EXCEPTION 'no confirmed store links found for roving hr_emploc %', p_id
        USING ERRCODE = '22023';
    END IF;

    INSERT INTO plantilla (
      account,              account_id,           chain_id,             province_id,
      position,             position_id,
      employee_no,          emploc_no,
      employee_name,        employee_name_snapshot,
      first_name,           middle_name,          last_name,
      civil_status,         date_of_birth,
      sss_no,               philhealth_no,         pagibig_no,
      date_hired,
      hrco_name,            hrco_user_id_snapshot,
      om_user_id_snapshot,  atl_user_id_snapshot,
      area,                 area_name_snapshot,
      hr_emploc_id,
      roving_assignment_id,
      deployment_type,
      status,               tagged_at,
      moved_by_user_id,     created_by,            updated_by,
      created_at,           updated_at
    )
    VALUES (
      v_emp.account, v_emp.account_id, v_emp.chain_id, v_emp.province_id,
      v_emp.position, v_emp.position_id_snapshot,
      v_emp.employee_no, v_emp.employee_no,
      v_formatted_name, v_formatted_name,
      v_app.first_name, v_app.middle_name, v_app.last_name,
      v_emp.civil_status_snapshot, v_emp.birthdate_snapshot,
      v_emp.sss_snapshot, v_emp.philhealth_snapshot, v_emp.pagibig_snapshot,
      v_emp.hired_date,
      v_emp.hrco_name, v_emp.hrco_user_id_snapshot,
      v_emp.om_user_id_snapshot, v_emp.atl_user_id_snapshot,
      v_emp.area_name_snapshot, v_emp.area_name_snapshot,
      v_emp.id,
      v_emp.roving_assignment_id,
      'Roving',
      'Active', CURRENT_DATE,
      v_actor, v_actor, v_actor,
      NOW(), NOW()
    )
    RETURNING * INTO v_pl;

    INSERT INTO public.plantilla_store_links (
      plantilla_id,
      roving_assignment_id,
      hr_emploc_store_link_id,
      vacancy_id,
      vcode,
      store_name,
      account,
      status,
      linked_at,
      linked_by,
      created_by,
      updated_by
    )
    SELECT
      v_pl.id,
      sl.roving_assignment_id,
      sl.id,
      sl.vacancy_id,
      sl.vcode,
      sl.store_name,
      sl.account,
      'Active',
      NOW(),
      v_actor,
      v_actor,
      v_actor
    FROM public.hr_emploc_store_links sl
    WHERE sl.hr_emploc_id = p_id
      AND sl.status       = 'Confirmed'
      AND sl.deleted_at   IS NULL;

    -- Close confirmed store vacancies via vacancy_id
    UPDATE public.vacancies
       SET status     = 'Filled',
           updated_at = NOW(),
           updated_by = v_actor
     WHERE id IN (
       SELECT vacancy_id
         FROM public.hr_emploc_store_links
        WHERE hr_emploc_id = p_id
          AND status       = 'Confirmed'
          AND deleted_at   IS NULL
          AND vacancy_id   IS NOT NULL
     )
     AND status NOT IN ('Filled', 'Closed', 'Archived');

    -- VCODE fallback: close any remaining Open vacancy for the roving VCODE
    UPDATE public.vacancies
       SET status     = 'Filled',
           updated_at = NOW(),
           updated_by = v_actor
     WHERE vcode      = v_emp.vcode
       AND status     IN ('Open', 'For Sourcing')
       AND COALESCE(is_archived, false) = false
       AND deleted_at IS NULL;

  -- ── STATIONARY PATH / CGCODE COVERAGE SUB-PATH ─────────────────────────────
  ELSE

    IF v_emp.coverage_slot_id IS NOT NULL THEN
      -- ── CGCODE COVERAGE SUB-PATH ───────────────────────────────────────────
      INSERT INTO plantilla (
        account,              account_id,           chain_id,             province_id,
        position,             position_id,
        employee_no,          emploc_no,
        employee_name,        employee_name_snapshot,
        first_name,           middle_name,          last_name,
        civil_status,         date_of_birth,
        sss_no,               philhealth_no,         pagibig_no,
        date_hired,           vacancy_id,            vacancy_code_snapshot,
        vcode,
        hrco_name,            hrco_user_id_snapshot,
        om_user_id_snapshot,  atl_user_id_snapshot,
        area,                 area_name_snapshot,
        hr_emploc_id,
        coverage_slot_id,     coverage_group_id,
        deployment_type,
        status,               tagged_at,
        moved_by_user_id,     created_by,            updated_by,
        created_at,           updated_at
      )
      VALUES (
        v_emp.account, v_emp.account_id, v_emp.chain_id, v_emp.province_id,
        v_emp.position, v_emp.position_id_snapshot,
        v_emp.employee_no, v_emp.employee_no,
        v_formatted_name, v_formatted_name,
        v_app.first_name, v_app.middle_name, v_app.last_name,
        v_emp.civil_status_snapshot, v_emp.birthdate_snapshot,
        v_emp.sss_snapshot, v_emp.philhealth_snapshot, v_emp.pagibig_snapshot,
        v_emp.hired_date, v_emp.vacancy_id, v_emp.vacancy_code_snapshot,
        v_emp.vcode,
        v_emp.hrco_name, v_emp.hrco_user_id_snapshot,
        v_emp.om_user_id_snapshot, v_emp.atl_user_id_snapshot,
        v_emp.area_name_snapshot, v_emp.area_name_snapshot,
        v_emp.id,
        v_emp.coverage_slot_id, v_emp.coverage_group_id,
        'Roving',
        'Active', CURRENT_DATE,
        v_actor, v_actor, v_actor,
        NOW(), NOW()
      )
      RETURNING * INTO v_pl;

      -- Close carrier CGCODE vacancy via vacancy_id if available
      IF v_emp.vacancy_id IS NOT NULL THEN
        UPDATE vacancies
           SET status     = 'Filled',
               updated_at = NOW(),
               updated_by = v_actor
         WHERE id = v_emp.vacancy_id;
      END IF;

      -- VCODE fallback: close any remaining Open carrier vacancy
      UPDATE public.vacancies
         SET status     = 'Filled',
             updated_at = NOW(),
             updated_by = v_actor
       WHERE vcode      = v_emp.vcode
         AND status     IN ('Open', 'For Sourcing')
         AND COALESCE(is_archived, false) = false
         AND deleted_at IS NULL;

    ELSE
      -- ── PURE STATIONARY PATH ──────────────────────────────────────────────
      IF EXISTS (
        SELECT 1 FROM plantilla
         WHERE employee_no = v_emp.employee_no
           AND is_deleted  = false
           AND status IN ('Active', 'For Deactivation', 'On Leave')
      ) THEN
        RAISE EXCEPTION 'plantilla already has active record for employee_no %',
          v_emp.employee_no USING ERRCODE = '23505';
      END IF;

      INSERT INTO plantilla (
        account,              account_id,            chain_id,             store_id,
        store_name,           position,              position_id,
        province_id,
        employee_no,          emploc_no,
        employee_name,        employee_name_snapshot,
        first_name,           middle_name,           last_name,
        civil_status,         date_of_birth,
        sss_no,               philhealth_no,          pagibig_no,
        date_hired,           vacancy_id,              vacancy_code_snapshot,
        vcode,
        hrco_name,            hrco_user_id_snapshot,
        om_user_id_snapshot,  atl_user_id_snapshot,
        area,                 area_name_snapshot,
        hr_emploc_id,
        status,               tagged_at,
        moved_by_user_id,     created_by,              updated_by,
        created_at,           updated_at
      )
      VALUES (
        v_emp.account,        v_emp.account_id,       v_emp.chain_id,       v_emp.store_id,
        v_emp.store_name,     v_emp.position,         v_emp.position_id_snapshot,
        v_emp.province_id,
        v_emp.employee_no,    v_emp.employee_no,
        v_formatted_name,     v_formatted_name,
        v_app.first_name,     v_app.middle_name,      v_app.last_name,
        v_emp.civil_status_snapshot, v_emp.birthdate_snapshot,
        v_emp.sss_snapshot,   v_emp.philhealth_snapshot, v_emp.pagibig_snapshot,
        v_emp.hired_date,     v_emp.vacancy_id,        v_emp.vacancy_code_snapshot,
        v_emp.vcode,
        v_emp.hrco_name,      v_emp.hrco_user_id_snapshot,
        v_emp.om_user_id_snapshot, v_emp.atl_user_id_snapshot,
        v_emp.area_name_snapshot, v_emp.area_name_snapshot,
        v_emp.id,
        'Active',             CURRENT_DATE,
        v_actor, v_actor, v_actor, NOW(), NOW()
      )
      RETURNING * INTO v_pl;

    END IF; -- end coverage/pure-stationary split

  END IF; -- end pool/roving/stationary split

  -- ── 5. FINALIZE SLOT (Mark slot filled & link occupant) ───────────────────
  IF v_slot_id IS NOT NULL THEN
    v_slot_auth := public.fn_set_slot_status(
      p_slot_id               => v_slot_id,
      p_new_status            => 'filled',
      p_reason_code           => NULL,
      p_performed_by          => v_actor,
      p_remarks               => 'move_to_plantilla: slot filled by plantilla ' || v_pl.id::text,
      p_occupant_plantilla_id => v_pl.id
    );
    IF (v_slot_auth->>'status') NOT IN ('ok', 'no_op') THEN
      RAISE EXCEPTION 'move_to_plantilla: slot % finalization blocked: %',
        v_slot_id, COALESCE(v_slot_auth->>'blocked_reason', 'unknown')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  -- ── Vacancy Closure for Pure Stationary Path ─────────────────────────────
  IF NOT v_is_pool AND COALESCE(v_emp.assignment_type, 'Stationary') <> 'Roving' AND v_emp.coverage_slot_id IS NULL THEN
    IF v_emp.vacancy_id IS NOT NULL THEN
      UPDATE vacancies
         SET status     = 'Filled',
             updated_at = NOW(),
             updated_by = v_actor
       WHERE id = v_emp.vacancy_id
         AND NOT EXISTS (
           SELECT 1 FROM public.plantilla_slots ps
           WHERE ps.legacy_vcode = v_emp.vcode
             AND ps.is_roving    = false
             AND ps.slot_status IN ('open', 'pipeline', 'hr_processing')
         );
    END IF;

    UPDATE public.vacancies
       SET status     = 'Filled',
           updated_at = NOW(),
           updated_by = v_actor
     WHERE vcode      = v_emp.vcode
       AND status     IN ('Open', 'For Sourcing')
       AND COALESCE(is_archived, false) = false
       AND deleted_at IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.plantilla_slots ps
         WHERE ps.legacy_vcode = v_emp.vcode
           AND ps.is_roving    = false
           AND ps.slot_status IN ('open', 'pipeline', 'hr_processing')
       );
  END IF;

  -- ── Common: update hr_emploc status ─────────────────────────────────────────
  UPDATE hr_emploc
     SET status                = 'Moved to Plantilla',
         hr_status             = 'Transferred',
         moved_to_plantilla_at = NOW(),
         moved_to_plantilla_by = v_actor,
         updated_at            = NOW(),
         updated_by            = v_actor
   WHERE id = p_id;

  PERFORM log_audit_event('plantilla', 'INSERT', v_pl.id, NULL, to_jsonb(v_pl));
  PERFORM log_audit_event('hr_emploc', 'UPDATE', p_id, to_jsonb(v_emp),
                          to_jsonb((SELECT h FROM hr_emploc h WHERE h.id = p_id)));

  IF v_emp.coverage_slot_id IS NOT NULL THEN
    PERFORM public.fn_sync_coverage_slot_to_active(
      p_coverage_slot_id => v_emp.coverage_slot_id,
      p_plantilla_id     => v_pl.id,
      p_performed_by     => v_actor,
      p_source_fn        => 'move_to_plantilla'
    );
  END IF;

  RETURN v_pl;

-- ── 6. FAILURE SAFETY (Rollback Revert) ──────────────────────────────────────
EXCEPTION WHEN OTHERS THEN
  IF v_slot_id IS NOT NULL THEN
    UPDATE public.plantilla_slots
    SET slot_status = 'open',
        updated_at = NOW()
    WHERE id = v_slot_id;
  END IF;
  IF v_pool_slot_id IS NOT NULL THEN
    UPDATE public.workforce_pool_slots
       SET status = 'open',
           occupant_employee_id = NULL,
           updated_at = NOW()
     WHERE id = v_pool_slot_id;
  END IF;
  RAISE;
END
$function$

;

REVOKE ALL ON FUNCTION public.move_to_plantilla(p_id uuid) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.move_to_plantilla(p_id uuid) TO authenticated;
